/**
 * Universal Physics Tensor — Bridge Equation Index
 *
 * Machine-readable catalog of all 40 bridge equations from the UPT specification
 * (Parts I-VI). Each entry preserves the spec's stated status, known issues,
 * references, and dependencies on other bridge equations.
 *
 * Generated by scripts/extract.py (~/.claude/playground/upt_bridge_extraction/);
 * see data/bridges/README.md for regen instructions.
 *
 * Source-of-truth files: docs/specification/Part-{I-VI}.md
 *
 * Honest-claude: fields not explicitly stated in the spec are null (not guessed).
 * - dimensional_signature is null for not-yet-encoded entries. Populated for
 *   hand-encoded equations (currently 11, 14, 18, 29, 47, 48) — see
 *   `src/bridges/equations/`. Populated values are exactly what
 *   `format()` produces for the inferred Dimension shape; never free-form prose.
 * - known_issues are extracted ONLY from explicit issue-markers in the spec
 *   ("**Known issue:**", "**Additional known issue:**", "**Bound violation:**",
 *   etc.). Equations whose Status text discusses problems narratively without
 *   such a marker have known_issues: [] — see status_text appended in `notes`.
 *
 * @module bridges
 */

export type BridgeEquationStatus =
  | 'established'
  | 'speculative'
  | 'highly-speculative'
  | 'invalid';

/**
 * Type predicate: an "active" status is one where the entry is part of
 * ongoing research (established / speculative / highly-speculative). The
 * 'invalid' status marks deprecated or self-refuting entries (BE-16
 * today) that should be excluded from active-research summaries,
 * tier-promotion candidate pools, and dimensional-encoding queues.
 *
 * Use as: `BRIDGE_EQUATIONS.filter((e) => isActiveStatus(e.status))`.
 *
 * Source: type-design-expert Critical-Hole on the 'invalid' arm.
 */
export function isActiveStatus(
  s: BridgeEquationStatus,
): s is Exclude<BridgeEquationStatus, 'invalid'> {
  return s !== 'invalid';
}

export type BridgeIssueSeverity =
  | 'self-refuting'
  | 'dimensional'
  | 'index-structure'
  | 'sign'
  | 'undefined-quantity'
  | 'phenomenological-ansatz'
  | 'other';

export type BridgeIssueFixable =
  | 'spec-edit'
  | 'reformulation'
  | 'unfixable-must-mark-invalid'
  | 'unknown';

/**
 * Tractability class — added 2026-05-05 (Wave I.B D10, per CS reviewer I5).
 * Bridge equations span a wide range of computational tractability:
 * - 'closed-form': evaluable in O(1) via algebraic identities (e.g.,
 *   BE-11 Caldeira-Leggett rate, BE-14 Ryu-Takayanagi entropy).
 * - 'numerical-tractable': admits a polynomial-time numerical algorithm
 *   (e.g., BE-26 1D WKB integral, BE-47 BBN ODE system).
 * - 'numerical-asymptotic': admits asymptotic-series approximations
 *   that diverge at finite truncation depth (rare in this catalog).
 * - 'formally-divergent': the closed-form is not a Turing-computable
 *   number (e.g., BE-20 cosmological-constant integral, BE-50
 *   distributional path integral). UPT documents but does not claim
 *   to compute these.
 * - 'undefined': not yet classified (default for entries not in the
 *   9 AST-encoded set).
 */
export type BridgeTractabilityClass =
  | 'closed-form'
  | 'numerical-tractable'
  | 'numerical-asymptotic'
  | 'formally-divergent'
  | 'undefined';

export interface KnownIssue {
  severity: BridgeIssueSeverity;
  /** Verbatim issue text from the spec (may be paraphrased; cf. source). */
  description: string;
  fixable: BridgeIssueFixable;
}

export interface BridgeEquationEntry {
  /** Equation number, 11-50. */
  id: number;
  /** Verbatim heading text from the spec. */
  name: string;
  /** Category letter (A-O). */
  category: string;
  /** Category display name, e.g. "Quantum-Classical Bridges". */
  category_name: string;
  /** Two-element tuple naming the bridged regimes. */
  bridges: [string, string];
  status: BridgeEquationStatus;
  /** 1-2 sentence summary from the spec's Context bullet. */
  context: string;
  /** Primary equation as LaTeX, decoded from upmath SVG src. */
  formula_latex: string | null;
  source_part: 'I' | 'II' | 'III' | 'IV' | 'V' | 'VI';
  source_section: string;
  known_issues: KnownIssue[];
  /** arXiv IDs and other identifiers as cited in the spec. */
  references: string[];
  /** IDs of other bridge equations explicitly referenced in this entry. */
  dependencies: number[];
  /** SI dimensional signature (null = not yet analyzed; Tier 4 work). */
  dimensional_signature: string | null;
  /**
   * Tractability class — Wave I.B D10 (2026-05-05). Distinguishes
   * closed-form / numerical-tractable / formally-divergent / etc.
   * Defaults to 'undefined' for entries not yet classified.
   */
  tractability_class: BridgeTractabilityClass;
  /** Free-form notes (origin Status text appended for traceability). */
  notes: string;
}

